    "sec02_coverStory": {
      "sectionTitle": "BÀI ĐINH TRANG NHẤT · COVER STORY",
      "editorialHeadline": "Tỷ giá trung tâm lập kỷ lục 25.668 đồng, cuộc đua giữ CASA bùng nổ giữa áp lực khối ngoại bán ròng 127.000 tỷ",
      "editorialSubheadline": "Phiên đầu tuần 23/11 ghi nhận NHNN nâng tỷ giá trung tâm lên 25.668 VND/USD, nhóm ngân hàng bước vào cuộc chiến giành tài khoản chính khi lãi suất huy động ưu đãi chạm 7,2%/năm, còn VN-Index mở cửa lùi về 1.683,27 điểm.",
      "dek": "Chỉ 8/28 ngân hàng niêm yết giữ được tăng trưởng tỷ lệ CASA hết quý III/2026 buộc các nhà băng đẩy mạnh hệ sinh thái số và ưu đãi tiền gửi, trong khi dòng vốn ngoại rút ròng kỷ lục gần 127.000 tỷ đồng trên HoSE thử thách tâm lý thị trường.",
      "executiveSummary": "Sáng 23/11, tỷ giá trung tâm tăng thêm 9 đồng lên kỷ lục 25.668 VND/USD khi Vietcombank bán ra sát mốc 26.000 đồng. Cùng lúc, áp lực CASA sụt giảm buộc Techcombank, MB và Big4 tăng tốc giữ dòng tiền tài khoản chính với lãi suất ưu đãi tới 7,2%/năm. Trên sàn HoSE, VN-Index lùi về 1.683,27 điểm.",
      "leadArticle": {
        "headline": "Cuộc chiến \"tài khoản chính\" trên điện thoại người Việt: Techcombank, MB đua hệ sinh thái; Vietcombank, BIDV, VietinBank và VPBank xoay xở thế nào?",
        "eventId": "EVT-32",
        "sourceName": "CafeF / VCCorp",
        "publishedAt": "23/11/2026 08:00 | Nguồn gốc: CafeF / VCCorp (2026-11-23T08:00:00+07:00)",
        "sourceUrl": "https://cafef.vn/cuoc-chien-tai-khoan-chinh-tren-dien-thoai-nguoi-viet-techcombank-mb-dua-he-sinh-thai-vietcombank-bidv-vietinbank-va-vpbank-xoay-xo-the-nao-188261123080059829.chn",
        "summary": "Sáng 23/11, tỷ giá trung tâm tăng thêm 9 đồng lên kỷ lục 25.668 VND/USD khi Vietcombank bán ra sát mốc 26.000 đồng. Cùng lúc, áp lực CASA sụt giảm buộc Techcombank, MB và Big4 tăng tốc giữ dòng tiền tài khoản chính với lãi suất ưu đãi tới 7,2%/năm. Trên sàn HoSE, VN-Index lùi về 1.683,27 điểm.",
        "supportingQuote": "Khi giao diện ứng dụng ngân hàng đã đạt mặt bằng tương đồng, khả năng giữ dòng tiền thanh toán hằng ngày trở thành thước đo sống còn cho tỷ lệ CASA và biên lãi ròng của toàn hệ thống.",
        "imageUrl": "https://cafefcdn.com/thumb_w/1200/203337114487263232/2026/11/23/avatar1795395573620-1795395574232286705766.png"
      },
      "imageUrl": "https://cafefcdn.com/thumb_w/1200/203337114487263232/2026/11/23/avatar1795395573620-1795395574232286705766.png",
      "supportingQuote": "Khi giao diện ứng dụng ngân hàng đã đạt mặt bằng tương đồng, khả năng giữ dòng tiền thanh toán hằng ngày trở thành thước đo sống còn cho tỷ lệ CASA và biên lãi ròng của toàn hệ thống.",
      "editorialPullQuote": "Khi giao diện ứng dụng ngân hàng đã đạt mặt bằng tương đồng, khả năng giữ dòng tiền thanh toán hằng ngày trở thành thước đo sống còn cho tỷ lệ CASA và biên lãi ròng của toàn hệ thống.",
      "pullQuote": "Khi giao diện ứng dụng ngân hàng đã đạt mặt bằng tương đồng, khả năng giữ dòng tiền thanh toán hằng ngày trở thành thước đo sống còn cho tỷ lệ CASA và biên lãi ròng của toàn hệ thống.",
      "editorialSynthesis": "Bốn chuyển động trọng yếu của phiên sáng 23/11/2026 từ 40 bản tin xác minh 0–24h: (1) Áp lực tỷ giá & cuộc đua giữ CASA ngân hàng: NHNN nâng tỷ giá trung tâm lên đỉnh kỷ lục 25.668 VND/USD (+9đ), Vietcombank bán ra 25.990–26.020đ và BIDV niêm yết 25.995–26.005đ; trong bối cảnh chỉ 8/28 ngân hàng niêm yết tăng được CASA quý III, VPBank tung Hũ Mục Tiêu lãi suất tới 7,2%/năm còn BIDV siết bảo mật iOS trước mã độc DarkSword; (2) Chứng khoán giằng co dưới 1.700 điểm & vốn ngoại rút ròng kỷ lục: VN-Index chốt tuần 20/11 tại 1.688,79 điểm và sáng 23/11 lùi về 1.683,27 điểm khi khối ngoại bán ròng lũy kế gần 127.000 tỷ đồng trên HoSE (riêng nhóm ngân hàng 47.376 tỷ đồng) và nhiều thương vụ tăng vốn phải gia hạn; (3) Hạ tầng năng lượng, giao thông & khung pháp lý mới: Quốc hội thông qua Luật Kinh doanh bất động sản sửa đổi hiệu lực 01/7/2027, Gulf Energy đề xuất đầu tư 1,5 tỷ USD xây siêu kho LNG tại Thanh Hóa, Tây Ninh chuẩn bị khởi công 3 tuyến đường hơn 30.000 tỷ đồng và EVNNPT đóng điện trạm 220kV Lai Uyên tại TP.HCM; (4) Vàng SJC bật tăng trở lại & tiêu dùng số phân hóa: Giá vàng miếng SJC sáng 23/11 tăng 1,5 triệu đồng/lượng lên 135 triệu đồng/lượng theo đà hồi phục của vàng thế giới lên 3.615 USD/oz, trong khi Việt Nam trở thành điểm sáng duy nhất Đông Nam Á tăng trưởng doanh số smartphone (+1% quý III) và đẩy mạnh thương mại trực tiếp qua livestream nông sản.",
      "marketImpact": "(1) Doanh nghiệp xuất nhập khẩu và thương mại đối diện chi phí ngoại tệ tăng khi giá bán USD ngân hàng tiến sát 26.000 đồng và kỳ vọng Fed tiếp tục tăng lãi suất tháng 12. (2) Kênh tiền gửi tiết kiệm trực tuyến và sản phẩm tích lũy nhóm lãi suất 6,8–7,2%/năm hút dòng tiền nhàn rỗi rời khỏi chứng khoán ngắn hạn. (3) Các chuỗi bán lẻ điện máy, trang sức và dịch vụ B2B cần tối ưu dòng tiền thu hộ tức thì và trả góp 0% để duy trì sức mua cuối năm.",
      "fintechLensAction": "Trước cuộc đua giữ tài khoản chính của ngân hàng và nhu cầu tiêu dùng mùa cao điểm, Payoo tích hợp thanh toán QR đa ngân hàng, trả góp 0% trên SmartPOS cùng tính năng Dynamic Currency Conversion (DCC) cho 19,5 triệu lượt khách quốc tế giúp điểm bán tăng doanh thu và thu tiền tức thì 24/7.",
      "monitoringWatchpoint": "Theo dõi diễn biến tỷ giá ngân hàng quanh ngưỡng 26.000 VND/USD, vùng hỗ trợ 1.650–1.680 điểm của VN-Index và biểu lãi suất huy động 12 tháng cuối tháng 11.",
      "whyItMatters": "(1) Doanh nghiệp xuất nhập khẩu và thương mại đối diện chi phí ngoại tệ tăng khi giá bán USD ngân hàng tiến sát 26.000 đồng và kỳ vọng Fed tiếp tục tăng lãi suất tháng 12. (2) Kênh tiền gửi tiết kiệm trực tuyến và sản phẩm tích lũy nhóm lãi suất 6,8–7,2%/năm hút dòng tiền nhàn rỗi rời khỏi chứng khoán ngắn hạn. (3) Các chuỗi bán lẻ điện máy, trang sức và dịch vụ B2B cần tối ưu dòng tiền thu hộ tức thì và trả góp 0% để duy trì sức mua cuối năm.",
      "keyMarketImplication": "Trước cuộc đua giữ tài khoản chính của ngân hàng và nhu cầu tiêu dùng mùa cao điểm, Payoo tích hợp thanh toán QR đa ngân hàng, trả góp 0% trên SmartPOS cùng tính năng Dynamic Currency Conversion (DCC) cho 19,5 triệu lượt khách quốc tế giúp điểm bán tăng doanh thu và thu tiền tức thì 24/7."
    },
